SELECT store.s_store_name, store.s_city, store.s_state, store_sales.ss_quantity, store_sales.ss_sales_price, (store_sales.ss_quantity * store_sales.ss_sales_price) AS total_sales_amount, (store_sales.ss_sales_price - store_sales.ss_wholesale_cost) AS margin_per_item, CASE WHEN store_sales.ss_quantity > 93 THEN 'Bulk' ELSE 'Regular' END AS quantity_category, CASE WHEN store.s_state = 'MN' THEN 'TargetState' ELSE store.s_state END AS state_label FROM store_sales INNER JOIN store ON store_sales.ss_store_sk = store.s_store_sk WHERE store_sales.ss_sold_date_sk >= 2452252
